 console.log(JSON.stringify({pass:true,version:sdk.cli.CLI_VERSION,runtime:'actual compiled Node CLI/SDK/worker/HTTP collector',checks,nativeTlsVerified,modelRequests:generations,inputCountingRequests:counts,companyRequests:0,toolCalls:0,personalSettingsModified:false,centralWormVerified:false,semanticEquivalenceVerified:false},null,2));
